<section class="phero"><img class="phero-bg" src="/assets/img/photos/insurance-paperwork.webp" srcset="/assets/img/photos/insurance-paperwork-640.webp 640w, /assets/img/photos/insurance-paperwork.webp 960w" sizes="100vw" width="960" height="640" alt="" fetchpriority="high" decoding="async"><div class="wrap phero-in"><nav class="crumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">›</span><a href="/policyholder-tools/">Free tools</a><span aria-hidden="true">›</span>RCV / ACV Holdback Calculator</nav><p class="tag">Free calculator</p><h1>RCV and ACV Depreciation Holdback Calculator</h1><p class="lede">Most replacement cost policies pay actual cash value first and hold back depreciation until repairs are done. See both figures item by item.</p></div></section>
<section class="sec tool-sec"><div class="wrap">
<div class="tool tool-wide" data-tool="dep">
  <div class="tool-head"><span>RCV / ACV holdback calculator</span><i>Add a row per item</i></div>
  <div class="tool-body">
    <div class="tool-in">
      <div class="table-wrap items-table"><table><thead><tr><th scope="col">Item</th><th scope="col">Replacement cost ($)</th><th scope="col">Age (yrs)</th><th scope="col">Life (yrs)</th><th scope="col">ACV</th><th scope="col"><span class="sr-only">Remove</span></th></tr></thead><tbody>
      <tr><td><input name="item" value="Asphalt shingle roof" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="21400" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="12" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="25" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Vinyl siding — two elevations" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="7800" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="15" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="30" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr><tr><td><input name="item" value="Plaster ceiling & paint — second floor" aria-label="Item"></td><td><input name="rcv" inputmode="decimal" value="4300" aria-label="Replacement cost"></td><td><input name="age" inputmode="decimal" value="20" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="50" aria-label="Expected life in years"></td><td class="mono" data-o="row">$0</td><td><button type="button" class="x" aria-label="Remove row">×</button></td></tr>
      </tbody></table></div>
      <div class="btn-row"><button type="button" class="btn line small" data-add data-run>+ Add item</button></div>
      <div class="row2">
        <div><label for="d-ded">Deductible ($)</label><input id="d-ded" name="deduct" inputmode="decimal" value="1500"></div>
        <div><label for="d-cap">Depreciation cap</label><select id="d-cap" name="cap"><option value="50">50%</option><option value="60">60%</option><option value="75" selected>75%</option><option value="80">80%</option><option value="90">90%</option></select><span class="hint">Estimates often cap how much an item can depreciate.</span></div>
      </div>
      <label class="check"><input type="checkbox" name="nonrec"> My policy pays actual cash value only (depreciation isn’t recoverable)</label>
    </div>
    <div class="tool-out tool-out-grid" aria-live="polite">
      <div class="out-big"><small>First payment (ACV − deductible)</small><b data-o="first">$0</b></div>
